# #057①：api_token 加唯一约束。加约束前必须先把历史数据里的空串/重复值补掉 ——
# 否则 AlterField 会直接 IntegrityError 把部署卡住（本地就已有 1 个空 token 用户）。

import secrets

from django.db import migrations, models


def fill_blank_and_duplicate_tokens(apps, schema_editor):
    """给空 token / 重复 token 的用户重新发一个（token 等同登录态，重复等于能登错号）。"""
    User = apps.get_model('users', 'User')
    seen = set()
    for user in User.objects.all().order_by('pk'):
        token = (user.api_token or '').strip()
        if not token or token in seen:
            token = secrets.token_hex(32)
            while token in seen:
                token = secrets.token_hex(32)
            User.objects.filter(pk=user.pk).update(api_token=token)
        seen.add(token)


class Migration(migrations.Migration):

    dependencies = [
        ('users', '0005_user_openid'),
    ]

    operations = [
        migrations.RunPython(fill_blank_and_duplicate_tokens, migrations.RunPython.noop),
        migrations.AlterField(
            model_name='user',
            name='api_token',
            field=models.CharField(blank=True, max_length=64, unique=True, verbose_name='API令牌'),
        ),
    ]
